function productStatus(p){if(!p)return 'Sin precio consultado';if(p.source==='manual')return 'Introducido por ti · '+stamp(p.fetchedAt);const status={current:'Consultado',stale:'Desactualizado: actualiza',failed:'Consulta fallida: actualiza',area:'Otra zona: actualiza',unavailable:'No disponible'};return 'Mercadona · CP '+p.postcode+' · '+(status[p.status]||'Consultado')+' · '+stamp(p.fetchedAt);}
