function recipeCostLabel(r){const cost=E.recipeCost(S,r);return cost===null?'Coste pendiente':euro(cost)+' calculados';}
function marketCard(edit=false){const invalid=Object.keys(I).filter(id=>!E.priced(E.product(S,id))).length;return `<div class="market-card mt"><p class="caption mb">Consulta publicada por GitHub Actions. «Actualizar» carga la última disponible; los importes de más de 24 h quedan pendientes.</p><p class="eyebrow">CATÁLOGO CON FUENTE · ${stamp(S.market.fetchedAt)}</p><div class="row between wrap"><div><h3>Mercadona · CP ${S.market.postcode}</h3><p class="small muted" data-market-progress>${marketBusy?`Consultando ${marketDone}/${marketCount}…`:invalid?`${invalid} ingrediente${invalid===1?'':'s'} del catálogo sin precio vigente`:'Precios publicados guardados con fecha'}</p></div>${!marketBusy?`<button class="text-btn" data-action="refresh-market">${icon('swap')} Actualizar</button>`:''}</div>${edit?`<form id="market-form" class="mt"><label class="small" for="market-postcode">Código postal de la compra</label><div class="row"><input class="input" id="market-postcode" name="postcode" inputmode="numeric" pattern="[0-9]{5}" maxlength="5" required value="${S.market.postcode}"><button type="submit" class="button" ${marketBusy?'disabled':''}>Consultar</button></div></form>`:''}</div>`;}
function budgetNotice(){const sum=E.summary(S);return `${sum.missing||sum.variable?`<p class="notice warn mt">Total pendiente: ${sum.missing} sin precio vigente y ${sum.variable} al peso. El presupuesto no se puede confirmar todavía.</p>`:''}${sum.knownTotal>S.prefs.budget?`<p class="notice warn mt">El subtotal con precio ya supera tu presupuesto en ${euro(sum.knownTotal-S.prefs.budget)}.</p>`:''}`;}
function refreshMarket(postcode){if(marketBusy){toast('La consulta sigue en curso');return;}if(!/^\d{5}$/.test(postcode)){toast('Introduce un código postal de cinco cifras');return;}if(!window.MesaNative?.updatePrices){toast('No se pudo iniciar la consulta');return;}
 marketBusy=true;marketToken=String(Date.now());marketDone=0;const ids=[...M.allowedIds()];marketCount=ids.length;
 if(postcode!==S.market.postcode){S.market.postcode=postcode;S.market.warehouse='pending';S.checks={};save();}
 native('updatePrices',postcode,JSON.stringify(ids),marketToken);clearTimeout(marketWatchdog);marketWatchdog=setTimeout(()=>{if(marketBusy)window.marketResult(marketToken,{fatal:'La consulta no ha terminado. Vuelve a abrir la app y actualiza.'});},2400000);render();if(modal?.type==='prices')pricesSheet();}
window.marketStarted=(token,result)=>{if(token!==marketToken)return;S.market.postcode=result.postcode;S.market.warehouse=result.warehouse;save();};
window.marketProgress=(token,result)=>{if(token!==marketToken)return;marketDone=result.done;marketCount=result.total;document.querySelectorAll('[data-market-progress]').forEach(el=>el.textContent=`Consultando ${marketDone}/${marketCount}…`);};
window.marketResult=(token,result)=>{if(token!==marketToken||!marketBusy)return;clearTimeout(marketWatchdog);marketBusy=false;
 if(result.fatal){for(const id of M.allowedIds())S.market.errors[id]=String(result.fatal).slice(0,300);save();render();toast('No se actualizaron los precios. '+result.fatal);if(modal?.type==='prices')pricesSheet();return;}
 const errors={};for(const id of M.allowedIds()){const record=result.records?.[id];try{if(!record)throw Error(result.errors?.[id]||'Sin respuesta');if(record.context.postcode!==S.market.postcode||record.context.warehouse!==S.market.warehouse)throw Error('Zona no confirmada');S.market.products[id]=M.validProduct(M.normalize(record.raw,record.context));}catch(e){errors[id]=String(e.message).slice(0,300);}}
 S.market.errors=errors;S.market.fetchedAt=result.fetchedAt;S.checks={};save();render();if(modal?.type==='prices')pricesSheet();else if(modal?.type==='price')priceSheet(modal.id);toast(Object.keys(errors).length?'Actualizado. Algunos productos no están disponibles.':'Última consulta publicada de Mercadona cargada');};
