 const navs=[['home','home','Hoy'],['explore','book','Recetas'],['plan','calendar','Mi menú'],['shop','bag','Compra'],['catalog','bag','Supermercados'],['pantry','fridge','Despensa'],['lab','spark','Studio'],['history','calendar','Mis menús']];
 $('sidebar').innerHTML=`<button class="brand" data-action="nav" data-page="home"><span class="brandmark">${icon('leaf')}</span><span>MesaChef<span class="orange">.</span><small>STUDIO</small></span></button><p class="rail-label">MI COCINA</p><div class="rail-nav">${navs.map(([id,ic,label])=>`<button class="rail-link ${page===id?'active':''}" data-action="nav" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='lab'?'<span class="tiny-badge">NUEVO</span>':''}</button>`).join('')}</div><div class="rail-bottom"><div class="rail-note">Tu cocina, sin cuotas.<span>Recetas propias y menús guardados a tu ritmo.</span></div><button class="profile" data-action="settings"><span class="avatar">${esc((S.prefs.name||'C').slice(0,1))}</span><span><b>${esc(S.prefs.name||'Chef')}</b><small>Cocina personal</small></span>${icon('settings')}</button></div>`;
 $('header').innerHTML=`<div class="crumb"><span>Mi cocina</span><span>/</span><b>${navs.find(x=>x[0]===page)?.[2]||'Preferencias'}</b></div><button class="mobile-brand brand" data-action="nav" data-page="home">${icon('leaf')} MesaChef<span class="orange">.</span></button><div class="head-right">${lastUndo?`<button class="text-btn undo-btn" data-action="undo">${icon('back')} Deshacer</button>`:''}<button class="search-trigger" data-action="command">${icon('search')}<span>Busca tu próxima idea</span><kbd>Ctrl K</kbd></button><button class="price-pill" data-action="prices"><span class="status-dot"></span><span>Mercadona · ${S.market.postcode}</span></button><button class="icon-btn" data-action="settings" aria-label="Preferencias">${icon('settings')}</button></div>`;
 $('nav').innerHTML=navs.filter(x=>['home','explore','plan','shop','catalog','pantry'].includes(x[0])).map(([id,ic,label])=>`<button class="nav-btn ${page===id?'active':''}" data-action="nav" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(ic)}<span>${id==='plan'?'Menú':id==='catalog'?'Catálogo':label}</span></button>`).join('');
 $('main').innerHTML=({home,explore,plan:planPage,shop:shopPage,catalog:catalogPage,pantry:pantryPage,settings:settingsPage,lab:labPage,history:historyPage}[page]||home)();
 for(const f of forms){const el=$(f.id);if(el&&el.closest('#main')){el.value=f.value;if(el.type==='checkbox')el.checked=f.checked;}}if(focus&&$(focus)?.closest('#main'))$(focus).focus();if(page==='catalog'&&window.MesaCatalog)MesaCatalog.mount($('catalog-app'),S.market.postcode);
