function filtered(){let list=R.filter(allowed);if(query){const q=normalize(query);list=list.filter(r=>normalize(r.title+' '+r.ingredients.map(i=>I[i.id].name).join(' ')).includes(q));}if(filter==='quick')list=list.filter(r=>r.time<=15);if(filter==='protein')list=list.filter(r=>r.protein>=25);if(filter==='vegan')list=list.filter(r=>r.vegan);if(filter==='saved')list=list.filter(r=>S.favorites.includes(r.id));if(filter==='pantry')list=list.filter(r=>r.ingredients.some(i=>E.pantryQty(S,i.id)>0)).sort((a,b)=>coverage(b)-coverage(a));return list;}
function coverage(r){return r.ingredients.filter(i=>E.pantryQty(S,i.id)>=i.g*S.prefs.people).length/r.ingredients.length;}
function exploreResults(){const list=filtered();return `<p class="result-count">${list.length} recetas · filtros de tus preferencias aplicados</p>${list.length?`<div class="recipe-grid">${list.map(card).join('')}</div>`:empty('search','Todavía no hay coincidencias','Prueba otro ingrediente o cambia tus filtros.','clear-search','Ver más recetas')}<p class="notice mt">Las recetas calculan cantidades por ración. Comprueba las etiquetas de los productos si tienes alergias.</p>`;}
function explore(){return `<p class="eyebrow">INSPIRACIÓN A DIARIO</p><div class="row between wrap"><h1>¿Qué te apetece?</h1><button class="button" data-action="new-recipe">${icon('plus')} Crear receta</button></div><div class="search">${icon('search')}<input class="input" id="search" type="search" placeholder="Receta o ingrediente…" value="${esc(query)}" aria-label="Buscar receta o ingrediente" autocomplete="off"></div><div class="chips">${[['all','Todo'],['quick','15 minutos'],['protein','Alta proteína'],['vegan','Vegetal'],['saved','Favoritas'],['pantry','Con lo que tengo']].map(([id,n])=>`<button class="chip ${filter===id?'active':''}" data-action="filter" data-filter="${id}">${n}</button>`).join('')}</div><div id="recipe-results">${exploreResults()}</div>`;}
function planPageLegacy(){const count=Object.keys(S.plan).length;
 if(!count)return `<p class="eyebrow">PLANIFICA A TU MANERA</p><h1>Una semana<br>que te encaja.</h1><p class="sub">${S.prefs.people} personas · ${S.prefs.days} días · ${S.prefs.meals.map(x=>mealNames[x].toLowerCase()).join(' y ')}</p><div class="card mb"><div class="row between"><div><p class="budget-label">PRESUPUESTO DE COMPRA</p><strong class="budget-value">${euro(S.prefs.budget)}</strong></div><span class="feature-icon">${icon('bag')}</span></div><p class="small muted mt">Busca variedad y una compra asequible teniendo en cuenta tu despensa.</p></div><button class="button full" data-action="generate">${icon('spark')} Generar mi menú</button><button class="text-btn full" data-action="settings">Ajustar personas, comidas y filtros</button><p class="notice mt">El presupuesto se aplica a las comidas que elijas, incluyendo envases completos y los extras de tu lista. Se usan precios publicados de productos concretos. El presupuesto queda pendiente si falta un precio o hay productos al peso.</p>`;
 selectedDay=Math.min(selectedDay,S.prefs.days-1);const date=E.dateAt(S.prefs.start,selectedDay),fullDate=date.toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'});const slots=S.prefs.meals.map(kind=>({key:selectedDay+'-'+kind,kind,slot:S.plan[selectedDay+'-'+kind]}));const macros=slots.filter(x=>x.slot).reduce((a,{slot})=>{const r=E.recipe(slot.id);for(const k of ['kcal','protein','carbs','fat'])a[k]+=r[k];return a;},{kcal:0,protein:0,carbs:0,fat:0});
 return `<p class="eyebrow">TU SEMANA, RESUELTA</p><div class="row between"><h1>Mi menú.</h1><button class="icon-btn" data-action="settings" aria-label="Ajustar menú">${icon('edit')}</button></div><p class="sub">${S.prefs.people} personas · ${S.prefs.days} días · recetas a tu ritmo</p><div class="card compact"><div class="row between"><div><span class="budget-label">TOTAL DE PRODUCTOS</span><div><b style="font-size:23px;color:var(--ink)">${euro(E.total(S))}</b><span class="small muted"> / ${euro(S.prefs.budget)}</span></div></div><button class="text-btn" data-action="nav" data-page="shop">Mi lista ${icon('arrow')}</button></div><div class="progress"><span style="width:${S.prefs.budget>0?Math.min(100,E.summary(S).knownTotal/S.prefs.budget*100):0}%"></span></div></div>${marketCard()}${budgetNotice()}<div class="row between wrap mt"><span class="eyebrow">DÍAS ${Math.floor(selectedDay/7)*7+1}–${Math.min(S.prefs.days,Math.floor(selectedDay/7)*7+7)}</span><div class="row"><button class="text-btn" data-action="week-prev" ${selectedDay<7?'disabled':''}>← Anteriores</button><button class="text-btn" data-action="week-next" ${Math.floor(selectedDay/7)*7+7>=S.prefs.days?'disabled':''}>Siguientes →</button></div></div><div class="day-strip" aria-label="Días del menú">${Array.from({length:Math.min(7,S.prefs.days-Math.floor(selectedDay/7)*7)},(_,i)=>{const d=Math.floor(selectedDay/7)*7+i;const dt=E.dateAt(S.prefs.start,d);return `<button class="day ${d===selectedDay?'active':''}" data-action="day" data-day="${d}" aria-label="${esc(dt.toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'}))}" aria-pressed="${d===selectedDay}"><span>${dt.toLocaleDateString('es-ES',{weekday:'short'}).replace('.','')}</span><b>${dt.getDate()}</b><i></i></button>`;}).join('')}</div><p class="eyebrow">${esc(fullDate)}</p>${slots.map(({key,kind,slot})=>`<div class="meal-head"><span>${mealNames[kind].toUpperCase()}</span><span>${slot?`${slot.servings} RACIONES`:''}</span></div>${slot?mealCard(slot,key):`<button class="feature" data-action="choose" data-key="${key}">${icon('plus')} Añadir ${mealNames[kind].toLowerCase()}</button>`}`).join('')}
 <div class="card mt"><p class="eyebrow">NUTRICIÓN ORIENTATIVA POR PERSONA</p><div class="nutrition">${nutrition(macros)}</div><p class="small muted">Solo las comidas planificadas de este día. No es un objetivo diario ni un plan nutricional personalizado.</p></div><div class="action-pair"><button class="button secondary" data-action="save-menu">${icon('heart')} Guardar menú</button><button class="button secondary" data-action="regen">${icon('swap')} Otra semana</button><button class="button secondary" data-action="share-plan">${icon('share')} Compartir</button></div><p class="notice mt">Fija tus platos favoritos con el candado; se conservarán al generar otra semana. El coste por ración reparte el precio del envase por cantidades usadas; solo se calcula con precios vigentes de envases fijos. Para cantidades: 1 L equivale a 1.000 g y un huevo a 55 g. La compra cuenta envases.</p>`;
}
function planPage(){let html=planPageLegacy();if(!Object.keys(S.plan).length)return html;const first=Math.floor(selectedDay/7)*7,board=`<div class="week-board" aria-label="Vista de la semana">${Array.from({length:Math.min(7,S.prefs.days-first)},(_,i)=>{const d=first+i,date=E.dateAt(S.prefs.start,d);return `<button class="week-column ${selectedDay===d?'active':''}" data-action="day" data-day="${d}" aria-pressed="${selectedDay===d}"><span>${esc(date.toLocaleDateString('es-ES',{weekday:'long'}))}</span><b>${date.getDate()}</b>${S.prefs.meals.map(kind=>{const slot=S.plan[d+'-'+kind];return `<span class="week-slot"><small>${mealNames[kind].toUpperCase()}</small><strong>${slot?esc(E.recipe(slot.id).title):'Por elegir'}</strong></span>`;}).join('')}</button>`;}).join('')}</div>`;return html.replace('</div><p class="eyebrow">','</div>'+board+'<p class="eyebrow">');}
function mealCard(slot,key){const r=E.recipe(slot.id),cooked=S.cooked.includes(key);return `<article class="meal"><button data-action="recipe" data-id="${r.id}" data-key="${key}" style="padding:0" aria-label="Ver ${esc(r.title)}"><img src="./mesachef/images/${r.image}.jpg" alt=""></button><div class="meal-info"><button data-action="recipe" data-id="${r.id}" data-key="${key}" style="padding:0;text-align:left"><h3>${esc(r.title)}</h3></button><p class="meal-meta">${r.time} min · ${recipeCostLabel(r)} / ración</p><div class="meal-controls"><button data-action="lock" data-key="${key}" aria-pressed="${slot.locked}">${icon(slot.locked?'lock':'unlock')} ${slot.locked?'Fijada':'Fijar'}</button><button data-action="choose" data-key="${key}">${icon('swap')} Cambiar</button><button data-action="cook" data-id="${r.id}" data-key="${key}">${icon(cooked?'check':'play')} ${cooked?'Hecha':'Cocinar'}</button></div></div></article>`;}
function nutrition(r){return [['kcal','kcal'],['protein','g proteína'],['carbs','g hidratos'],['fat','g grasas']].map(([key,label])=>`<div><b>${r[key]}</b><span>${label}</span></div>`).join('');}
function shopPage(){const list=E.shopping(S),summary=E.summary(S),count=list.length+S.extras.length,checked=list.filter(x=>S.checks[x.id]).length+S.extras.filter(x=>S.checks[x.id]).length,groups=[...new Set(list.map(x=>x.aisle))];
 return `<div class="page-heading"><div><p class="eyebrow">PRODUCTOS CONCRETOS · PRECIOS CON FUENTE</p><h1>Tu compra.<br><em>Sin dar más vueltas.</em></h1><p class="sub">Lo que te falta, en el formato que has elegido.</p></div><button class="button" data-action="extra">${icon('plus')} Añadir un extra</button></div><div class="shopping-layout"><div class="shopping-content"><div class="action-pair"><button class="button secondary" data-action="share-shop">${icon('share')} Compartir lista</button><button class="button secondary" data-action="prices">${icon('bag')} Productos y precios</button><button class="button secondary" data-action="lab-tab" data-tab="packs">${icon('spark')} Revisar envases</button></div>${groups.map(group=>`<p class="group-label">${esc(group)}</p><div class="shop-group">${list.filter(x=>x.aisle===group).map(x=>`<div class="shop-row ${S.checks[x.id]?'checked':''}"><button class="check" data-action="check" data-id="${x.id}" aria-label="Marcar ${esc(x.name)}" aria-pressed="${!!S.checks[x.id]}">${S.checks[x.id]?icon('check'):''}</button><button class="shop-product" data-action="price" data-id="${x.id}"><p class="shop-title">${esc(x.product?.name||x.name)}</p><p class="shop-sub">${esc(x.name)} · necesitas ${grams(x.need)}</p><p class="shop-sub">${x.packs!==null?`${x.packs} × ${productFormat(x.product,x.id)}`:productFormat(x.product,x.id)}</p><p class="shop-sub source">${esc(productStatus(x.product))}</p></button><span class="shop-price">${x.variable?esc(productPrice(x.product)):x.unknown?'Sin precio':euro(x.cost)}${x.variable?'<small>Pendiente de pesar</small>':''}</span></div>`).join('')}</div>`).join('')}${S.extras.length?`<p class="group-label">TUS EXTRAS · IMPORTES INTRODUCIDOS POR TI</p><div class="shop-group">${S.extras.map(x=>`<div class="shop-row"><button class="check" data-action="check" data-id="${x.id}" aria-label="Marcar ${esc(x.name)}" aria-pressed="${!!S.checks[x.id]}">${S.checks[x.id]?icon('check'):''}</button><div style="flex:1"><p class="shop-title">${esc(x.name)}</p><p class="shop-sub">${esc(x.qty)}</p></div><span class="shop-price">${euro(x.cost)}</span><button class="small-icon" data-action="delete-extra" data-id="${x.id}" aria-label="Eliminar ${esc(x.name)}">${icon('trash')}</button></div>`).join('')}</div>`:''}${!count?empty('bag','Tu lista está tranquila','Crea tu menú para saber qué necesitas o añade un producto.','generate','Crear mi menú'):''}${list.some(x=>S.checks[x.id]&&x.buy!==null)?`<button class="button full mt" data-action="stock">${icon('fridge')} Guardar envases comprados en despensa</button>`:''}<p class="caption mt">Los productos al peso se añaden a despensa con la cantidad realmente comprada. No se inventa el peso de una bandeja.</p></div><aside class="shopping-aside"><div class="shopping-summary"><p class="small">${summary.complete?'TOTAL DE PRODUCTOS':'SUBTOTAL CON PRECIO'}</p><h2>${euro(summary.knownTotal)}</h2><p class="small mt">${summary.complete?'Importes disponibles para todos los productos de la lista.':`${summary.missing} sin precio vigente · ${summary.variable} al peso. Total pendiente.`}</p><div class="progress"><span style="width:${count?checked/count*100:0}%"></span></div><p class="small">${checked} de ${count} marcados</p><p class="small mt">Presupuesto ${euro(S.prefs.budget)}</p></div>${marketCard()}${summary.knownTotal>S.prefs.budget?`<p class="notice warn mt">El subtotal supera tu presupuesto en ${euro(summary.knownTotal-S.prefs.budget)}.</p>`:''}<p class="notice mt">Precios publicados por Mercadona para tu zona, con fecha. Pueden cambiar. El total excluye envío y básicos no listados.</p></aside></div>`;
}
function pantryPage(){const entries=Object.entries(S.pantry).sort((a,b)=>(a[1].expiry||'9999').localeCompare(b[1].expiry||'9999'));const soon=entries.filter(([id,p])=>p.expiry&&p.expiry<=E.localDate(E.dateAt(E.localDate(),3))).length;
 return `<p class="eyebrow">APROVECHA LO QUE YA TIENES</p><div class="row between"><h1>Mi despensa.</h1><button class="icon-btn" data-action="pantry-add" aria-label="Añadir alimento">${icon('plus')}</button></div><p class="sub">Menos desperdicio. Una compra más pequeña.</p>${soon?`<p class="notice warn mb">${soon} alimento${soon>1?'s':''} con fecha próxima o vencida. Los caducados no se descuentan de la compra.</p>`:''}${entries.length?`<div class="stack">${entries.map(([id,p])=>{const days=p.expiry?Math.round((new Date(p.expiry+'T12:00:00')-E.dateAt(E.localDate(),0))/86400000):null;return `<button class="pantry-item" data-action="pantry-edit" data-id="${id}"><span class="feature-icon">${icon('leaf')}</span><div><h3>${esc(I[id].name)}</h3><p>${grams(p.qty)} disponibles</p></div><span class="expiry ${days!==null&&days<=3?'urgent':''}">${days===null?'Sin fecha':days<0?'Fecha vencida':days===0?'Vence hoy':days===1?'Vence mañana':`En ${days} días`}<br>${p.expiry?esc(E.dateAt(p.expiry,0).toLocaleDateString('es-ES',{day:'numeric',month:'short'})):''}</span></button>`;}).join('')}</div>`:empty('fridge','Aquí empieza el ahorro','Añade los ingredientes que tienes en casa. El menú y la compra tendrán en cuenta esas cantidades.','pantry-add','Añadir mi primer alimento')}
 <button class="button secondary full mt" data-action="pantry-recipes">${icon('spark')} Recetas con lo que tengo</button><p class="notice mt">Introduce la cantidad utilizable: por ejemplo, garbanzos ya escurridos. La fecha sirve para organizarte; revisa siempre el envase y el estado del alimento.</p>`;
}
function settingsPage(){const p=S.prefs;return `<p class="eyebrow">TODO, A TU MEDIDA</p><h1>Tu forma<br>de comer.</h1><p class="sub">Puedes cambiar estas preferencias cuando quieras.</p>${marketCard(true)}<form id="settings-form"><div class="field"><label for="pref-name">Cómo te llamamos</label><input class="input" id="pref-name" name="name" maxlength="40" value="${esc(p.name)}"></div><div class="form-grid"><div class="field"><label for="pref-people">Personas</label><input class="input" id="pref-people" name="people" type="number" min="1" step="1" required value="${p.people}"></div><div class="field"><label for="pref-budget">Presupuesto (€)</label><input class="input" id="pref-budget" name="budget" type="number" min="0" step="0.01" required value="${p.budget}"></div></div><div class="form-grid"><div class="field"><label for="pref-days">Días de menú</label><input class="input" id="pref-days" name="days" type="number" min="1" step="1" value="${p.days}" required></div><div class="field"><label for="pref-start">Primer día</label><input class="input" id="pref-start" name="start" type="date" required value="${p.start}"></div></div><div class="setting-section"><h2>Qué comidas planificamos</h2>${Object.entries(mealNames).map(([id,n])=>`<div class="toggle-row"><input id="meal-${id}" name="meals" type="checkbox" value="${id}" ${p.meals.includes(id)?'checked':''}><label for="meal-${id}">${n}</label></div>`).join('')}</div><div class="setting-section"><h2>Preferencias de cocina</h2><div class="field"><label for="pref-diet">Tipo de alimentación</label><select id="pref-diet" name="diet">${[['all','Variada'],['vegetarian','Vegetariana'],['vegan','Vegana']].map(([id,n])=>`<option value="${id}" ${p.diet===id?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="pref-time">Tiempo máximo por receta</label><input class="input" id="pref-time" name="maxTime" type="number" min="1" step="1" value="${p.maxTime}" required></div><div class="toggle-row"><input id="pref-protein" name="protein" type="checkbox" ${p.protein?'checked':''}><label for="pref-protein">Priorizar proteína<span class="small muted" style="display:block">Mínimo 25 g en platos principales y 10 g en desayunos.</span></label></div></div><div class="setting-section"><h2>Ingredientes que evitas</h2><div class="allergy-grid">${Object.entries(allergenNames).map(([id,n])=>`<div class="toggle-row"><input id="allergen-${id}" name="allergens" type="checkbox" value="${id}" ${p.allergens.includes(id)?'checked':''}><label for="allergen-${id}">${n}</label></div>`).join('')}</div><p class="notice mt">El filtro usa los ingredientes del recetario; no certifica ausencia de trazas. Comprueba etiquetas y contaminación cruzada. La avena se trata como cereal con gluten.</p></div><div class="setting-section"><h2>Aspecto</h2><select name="theme" aria-label="Tema">${[['light','Claro · crema y verde'],['dark','Oscuro · verde noche']].map(([id,n])=>`<option value="${id}" ${p.theme===id?'selected':''}>${n}</option>`).join('')}</select></div><button type="submit" class="button full mt">${icon('check')} Guardar preferencias</button><p class="small muted mt">Al cambiar filtros se retiran del menú las recetas incompatibles. Cambiar personas ajusta las raciones; cambiar fechas inicia un nuevo registro de comidas.</p></form><div class="setting-section"><h2>Tus datos son tuyos</h2><button class="button secondary full mb" data-action="nav" data-page="history">${icon('calendar')} Mis menús guardados</button><button class="button secondary full mb" data-action="install">${icon('plus')} Añadir a pantalla de inicio</button><div class="stack"><button class="button secondary" data-action="export">${icon('download')} Exportar copia de seguridad</button><button class="button secondary" data-action="import">${icon('plus')} Restaurar copia</button><button class="text-btn" data-action="about">Qué incluye esta versión ${icon('arrow')}</button><button class="text-btn" data-action="reset" style="color:var(--danger)">Borrar mis datos</button></div></div><p class="small muted mt">MesaChef Studio · Sin anuncios ni rastreadores. Aplicación alojada en GitHub Pages. Datos guardados en este navegador. Sin cuotas de recetas, favoritos, menús guardados ni extras. La capacidad depende de tu navegador; exporta una copia para trasladar tus datos.</p>`;}
function showSheet(title,body,type,data={}){if(!modal)lastFocus=document.activeElement;modal={type,...data};$('overlay').hidden=false;$('sheet').innerHTML=`<div class="sheet-handle"></div><div class="sheet-head"><h2 id="sheet-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Cerrar">${icon('close')}</button></div>${body}`;document.body.style.overflow='hidden';$('app').inert=true;$('sheet').scrollTop=0;$('sheet').focus();}
function closeSheet(){const cooking=modal?.type==='cook';modal=null;$('overlay').hidden=true;document.body.style.overflow='';$('app').inert=false;if(cooking)native('keepAwake',false);if(lastFocus?.isConnected)lastFocus.focus();}
window.handleBack=()=>{if(modal){closeSheet();return true;}if(page!=='home'){goto('home');return true;}return false;};
function recipeSheet(id,key=null,keep=false){const r=E.recipe(id);if(!r)return;if(!keep)detailServings=key?S.plan[key].servings:S.prefs.people;const allerg=r.allergens.map(a=>allergenNames[a]);showSheet('A cocinar',`<img class="detail-image" src="./mesachef/images/${r.image}.jpg" alt=""><p class="caption">Fotografía ilustrativa · puede no representar este plato</p><h3 class="detail-title">${esc(r.title)}</h3><div class="detail-pills"><span class="pill">${icon('clock')} ${r.time} min</span><span class="pill">${recipeCostLabel(r)} / ración</span><span class="pill">${r.vegan?'Vegana':r.vegetarian?'Vegetariana':'Variada'}</span></div><div class="row between"><div><h3>Ingredientes</h3><p class="small muted">${detailServings} ración${detailServings===1?'':'es'} · pesos en crudo o escurridos</p></div><div class="stepper"><button data-action="servings" data-delta="-1" aria-label="Una ración menos" ${detailServings<=1?'disabled':''}>${icon('minus')}</button><b>${detailServings}</b><button data-action="servings" data-delta="1" aria-label="Una ración más" >${icon('plus')}</button></div></div>${r.ingredients.map(i=>`<div class="ingredient-line"><span>${esc(I[i.id].name)}${E.pantryQty(S,i.id)>=i.g*detailServings?' <span class="score">En casa</span>':''}</span><span>${grams(i.g*detailServings)}</span></div>`).join('')}<p class="small muted mt">${esc(r.spices)}. Equipamiento: ${esc(r.equipment)}.</p><div class="card mt compact"><p class="eyebrow">POR RACIÓN · VALORES ESTIMADOS</p><div class="nutrition">${nutrition(r)}</div><p class="small muted">Calculados a partir de valores genéricos de los ingredientes; varían por marca y preparación.</p></div><p class="notice ${allerg.length?'warn':''} mt">${allerg.length?'Ingredientes con: '+esc(allerg.join(', '))+'.':'Sin los alérgenos declarados en este recetario.'} Comprueba etiquetas y posibles trazas.</p><div class="section-title"><h2>Paso a paso</h2><button class="text-btn" data-action="fav" data-id="${r.id}">${icon('heart')} ${S.favorites.includes(r.id)?'Guardada':'Guardar'}</button></div><ol class="steps">${r.steps.map((s,i)=>`<li><span class="step-num">${i+1}</span><span>${esc(s)}</span></li>`).join('')}</ol>${r.note?`<p class="notice warn mt">${esc(r.note)}</p>`:''}<div class="sticky-actions"><button class="button secondary" data-action="schedule" data-id="${r.id}">${icon('calendar')} ${key?'Cambiar raciones':'Añadir al menú'}</button><button class="button" data-action="cook" data-id="${r.id}" ${key?`data-key="${key}"`:''}>${icon('play')} Modo cocina</button></div><button class="text-btn full mt" data-action="share-recipe" data-id="${r.id}">${icon('share')} Compartir receta</button>${r.custom?`<button class="text-btn full" data-action="edit-recipe" data-id="${r.id}">${icon('edit')} Editar mi receta</button>`:''}${key?`<button class="text-btn full" data-action="remove-meal" data-key="${key}" style="color:var(--danger)">${icon('trash')} Quitar del menú</button>`:''}`, 'recipe',{id,key});}
function chooseSheet(key){const kind=key.split('-')[1];const list=R.filter(r=>E.valid(r,S.prefs,kind));showSheet(`Elegir ${mealNames[kind].toLowerCase()}`,`<p class="small muted mb">Los filtros de tus preferencias ya están aplicados.</p>${list.length?list.map(r=>`<button class="list-choice" data-action="pick" data-id="${r.id}" data-key="${key}"><img src="./mesachef/images/${r.image}.jpg" alt=""><div><h3>${esc(r.title)}</h3><p>${r.time} min · ${r.protein} g proteína · ${recipeCostLabel(r)} / ración</p></div><span class="chevron">${icon('plus')}</span></button>`).join(''):empty('search','No hay opciones','Amplía el tiempo o cambia los filtros.','settings','Preferencias')}`,'choose',{key});}
function scheduleSheet(id){const oldKey=modal?.key;if(oldKey){S.plan[oldKey].servings=detailServings;S.cooked=S.cooked.filter(k=>k!==oldKey);S.batchChecks={};S.checks={};save();closeSheet();render();toast('Raciones actualizadas');return;}const r=E.recipe(id);const kinds=S.prefs.meals.filter(kind=>E.valid(r,S.prefs,kind));if(!kinds.length){toast('Esta receta no encaja en las comidas o filtros actuales');return;}showSheet('Añadir al menú',`<p class="sub">${esc(r.title)} · ${detailServings} raciones</p><form id="schedule-form" data-id="${id}"><div class="field"><label for="schedule-day">Día</label><select id="schedule-day" name="day">${Array.from({length:S.prefs.days},(_,d)=>`<option value="${d}">${esc(E.dateAt(S.prefs.start,d).toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'short'}))}</option>`).join('')}</select></div><div class="field"><label for="schedule-kind">Comida</label><select id="schedule-kind" name="kind">${kinds.map(kind=>`<option value="${kind}">${mealNames[kind]}</option>`).join('')}</select></div><p class="notice">Si ya hay una receta en ese hueco, se sustituirá. La nueva receta quedará fijada.</p><button type="submit" class="button full mt">${icon('plus')} Añadir ${detailServings} raciones</button></form>`,'schedule',{id});}
function pantrySheet(id=null){const p=id?S.pantry[id]:null;showSheet(id?'Editar alimento':'Añadir a despensa',`<form id="pantry-form" data-id="${id||''}"><div class="field"><label for="pantry-ing">Ingrediente</label><select id="pantry-ing" name="ingredient" ${id?'disabled':''}>${Object.values(I).sort((a,b)=>a.name.localeCompare(b.name,'es')).map(i=>`<option value="${i.id}" ${id===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select></div><div class="field"><label for="pantry-qty">Cantidad disponible (g)</label><input class="input" id="pantry-qty" name="qty" type="number" min="1" step="1" required value="${p?Math.round(p.qty):''}" placeholder="Ej. 500"></div><div class="field"><label for="pantry-date">Caducidad (opcional)</label><input class="input" id="pantry-date" name="expiry" type="date" value="${esc(p?.expiry||'')}"></div><p class="notice">${id?'Se reemplazan la cantidad y la fecha actuales.':'Si el ingrediente ya está en la despensa, se reemplazan su cantidad y su fecha.'} Introduce el total utilizable. Un huevo mediano equivale aproximadamente a 55 g sin cáscara.</p><button type="submit" class="button full mt">${icon('check')} Guardar alimento</button>${id?`<button type="button" class="text-btn full mt" data-action="pantry-delete" data-id="${id}" style="color:var(--danger)">${icon('trash')} Eliminar de despensa</button>`:''}</form>`,'pantry',{id});}
function extraSheet(){showSheet('Un extra para la lista',`<form id="extra-form"><div class="field"><label for="extra-name">Producto</label><input class="input" id="extra-name" name="name" maxlength="80" required placeholder="Ej. Café"></div><div class="form-grid"><div class="field"><label for="extra-qty">Cantidad</label><input class="input" id="extra-qty" name="qty" maxlength="40" placeholder="Ej. 1 paquete"></div><div class="field"><label for="extra-cost">Coste total (€)</label><input class="input" id="extra-cost" name="cost" type="number" min="0" step="0.01" value="" required></div></div><p class="notice">Los extras cuentan en el presupuesto. Se gestionan en la lista y no se incorporan automáticamente a la despensa.</p><button class="button full mt" type="submit">${icon('plus')} Añadir producto</button></form>`,'extra');}
function priceSheet(id){const receipt=S.receipts[id];showSheet('Producto y precio',`<h3>${esc(I[id].name)}</h3><p class="notice mt">${id==='fresa'?'Descongela según el envase. ':id==='pavo'?'Pica los filetes si la receta pide carne picada. ':''}Elige un producto concreto. Precio publicado por envase o tarifa al peso; fecha y fuente visibles.</p>${(window.PRODUCT_OPTIONS[id]||[]).map(pid=>{const product=S.market.products[pid],p=product?{...product,status:product.postcode!==S.market.postcode||product.warehouse!==S.market.warehouse?'area':S.market.errors[pid]?'failed':!product.available?'unavailable':!M.fresh(product)?'stale':'current'}:null;return `<div class="market-option"><button class="list-choice" data-action="select-product" data-id="${id}" data-product="${pid}" ${!E.priced(p)?'disabled':''}><div><h3>${esc(p?.name||'Producto '+pid)}</h3><p>${productFormat(p,id)} · ${E.priced(p)?esc(productPrice(p)):'Sin precio vigente'}</p><p>${esc(productStatus(p))}</p></div><span class="score">${S.market.selection[id]===pid&&!receipt?'Elegido':'Elegir'}</span></button>${p?`<button class="text-btn" data-action="source" data-product="${pid}">Ver ficha oficial ${icon('arrow')}</button>`:''}</div>`;}).join('')}<button class="button secondary full mt" data-action="refresh-market">${icon('swap')} Actualizar productos</button><details class="mt"><summary>Usar un precio de mi ticket</summary><form id="price-form" data-id="${id}"><p class="notice mt">Se guardará como introducido por ti y sustituirá el catálogo para este ingrediente.</p><div class="field"><label for="price-number">Precio pagado por envase (€)</label><input class="input" id="price-number" name="price" type="number" min="0" step="0.01" required value="${receipt?receipt.unitPriceCents/100:''}"></div><div class="field"><label for="price-pack">Cantidad utilizable real (g)</label><input class="input" id="price-pack" name="pack" type="number" min="1" step="1" required value="${receipt?.usableG||''}"></div><button class="button full" type="submit">Guardar precio del ticket</button></form></details>${receipt?`<button class="text-btn full mt" data-action="price-reset" data-id="${id}">Volver al precio del catálogo</button>`:''}`,'price',{id});}
function pricesSheet(){showSheet('Productos y precios',`${marketCard()}<p class="notice mt">Cada precio pertenece a un producto y una zona. Tras 24 horas se requiere actualizar para volver a incluirlo en el total.</p>${Object.values(I).sort((a,b)=>a.name.localeCompare(b.name,'es')).map(i=>{const p=E.product(S,i.id);return `<button class="list-choice" data-action="price" data-id="${i.id}"><span class="feature-icon">${icon('bag')}</span><div><h3>${esc(i.name)}</h3><p>${esc(p?.name||'Sin producto consultado')}</p><p>${E.priced(p)?esc(productPrice(p)):'Sin precio vigente'} · ${esc(productStatus(p))}</p></div><span class="chevron">${icon('chevron')}</span></button>`;}).join('')}`,'prices');}
function confirmSheet(title,text,action,label,data={}){showSheet(title,`<p class="sub">${text}</p><div class="action-pair"><button class="button secondary" data-action="close">Cancelar</button><button class="button" data-action="${action}" ${Object.entries(data).map(([k,v])=>`data-${k}="${esc(v)}"`).join(' ')}>${label}</button></div>`,'confirm',data);}
function generate(){const result=E.generate(S);if(result.error){toast(result.error);return;}rememberUndo();S.plan=result.plan;S.generation++;S.checks={};S.cooked=[];S.batchChecks={};save();selectedDay=0;goto('plan');toast(result.missing||result.variable?'Menú creado. Hay importes pendientes en la compra.':result.over>0.01?'Menú creado. Revisa el presupuesto.':'Tu semana y tu lista están listas');}
function startCook(id,key){const r=E.recipe(id);if(!r)return;if(key&&S.cooked.includes(key)){toast('Esta comida ya está marcada como cocinada');return;}const servings=modal?.type==='recipe'?detailServings:(key?S.plan[key].servings:S.prefs.people);cookStep=0;timerEnd=0;timerPaused=0;timerDone=false;native('keepAwake',true);cookSheet(id,key,servings);}
function cookSheet(id,key,servings){const r=E.recipe(id);showSheet('Modo cocina',`<p class="eyebrow">${esc(r.title)} · ${servings} RACIONES</p><div class="cook-progress">${r.steps.map((_,i)=>`<span class="${i<=cookStep?'done':''}"></span>`).join('')}</div><p class="eyebrow">PASO ${cookStep+1} DE ${r.steps.length}</p><p class="cook-step">${esc(r.steps[cookStep])}</p><div class="action-pair"><button class="button secondary" data-action="cook-prev" ${cookStep===0?'disabled':''}>${icon('back')} Anterior</button><button class="button" data-action="${cookStep===r.steps.length-1?'cook-finish':'cook-next'}">${cookStep===r.steps.length-1?'Terminar':'Siguiente'} ${icon('arrow')}</button></div><div class="timer"><h3>${icon('clock')} Tu temporizador</h3><p class="timer-display" id="timer-display">00:00</p><div class="row wrap"><label class="sr-only" for="timer-minutes">Minutos</label><input class="input" id="timer-minutes" type="number" min="1" step="1" value="5" aria-label="Minutos"><span class="small muted">min</span><button class="button" data-action="timer-start">Iniciar</button><button class="text-btn" data-action="timer-pause" id="timer-pause">${timerPaused?'Reanudar':'Pausar'}</button><button class="text-btn" data-action="timer-reset">Reiniciar</button></div><p class="small muted mt">Aviso visual dentro del modo cocina. Mantén la app abierta; no envía avisos en segundo plano.</p></div><p class="notice mt">La pantalla se mantiene encendida mientras está abierto este modo. Al terminar puedes descontar los ingredientes de tu despensa.</p>`,'cook',{id,key,servings});updateTimer();}
function updateTimer(){if(modal?.type!=='cook')return;let seconds=timerEnd?Math.max(0,Math.ceil((timerEnd-Date.now())/1000)):Math.ceil(timerPaused/1000);if(timerEnd&&seconds===0&&!timerDone){timerDone=true;toast('¡Tiempo terminado!');if(navigator.vibrate)navigator.vibrate([150,100,150]);}$('timer-display').textContent=timerDone?'¡Tiempo terminado!':`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if($('timer-pause'))$('timer-pause').textContent=timerPaused?'Reanudar':'Pausar';}
setInterval(updateTimer,500);
function finishCook(){const {id,key,servings}=modal;native('keepAwake',false);confirmSheet('¡Buen provecho!','¿Quieres marcar esta comida como hecha y descontar de la despensa los ingredientes disponibles? Los que no tengas no se descontarán.','consume','Hecha y descontar',{id,key:key||'',servings});}
function share(text){if(native('share',text))return;if(navigator.share){navigator.share({title:'MesaChef',text}).catch(()=>{});return;}showSheet('Texto para compartir',`<textarea class="input" rows="12" readonly>${esc(text)}</textarea><p class="small muted mt">Mantén pulsado para copiar el texto.</p>`,'share');}
function shopText(){const sum=E.summary(S);return `MI COMPRA · MesaChef\n${sum.complete?'Total de productos':'Subtotal con precio'}: ${euro(sum.knownTotal)}${sum.complete?'':' · total pendiente'}\nMercadona · CP ${S.market.postcode}\n\n`+E.shopping(S).map(x=>`${S.checks[x.id]?'✓':'□'} ${x.product?.name||x.name}: ${x.packs!==null?x.packs+' envases':'necesitas '+grams(x.need)} · ${x.variable?productPrice(x.product)+' · pendiente de pesar':euro(x.cost)} · ${productStatus(x.product)}${x.product?.url?'\n'+x.product.url:''}`).concat(S.extras.map(x=>`${x.name} ${x.qty} · ${euro(x.cost)} · introducido por ti`)).join('\n')+'\n\nExcluye envío y básicos no listados.';}
function planText(){const sum=E.summary(S);return `MI MENÚ · MesaChef\n\n`+Array.from({length:S.prefs.days},(_,d)=>E.dateAt(S.prefs.start,d).toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'short'})+'\n'+S.prefs.meals.map(kind=>{const slot=S.plan[d+'-'+kind];return `${mealNames[kind]}: ${slot?E.recipe(slot.id).title+' ('+slot.servings+' raciones)':'Sin planificar'}`;}).join('\n')).join('\n\n')+`\n\n${sum.complete?'Total de productos':'Subtotal con precio'}: ${euro(sum.knownTotal)}${sum.complete?'':' · total pendiente'}. Mercadona CP ${S.market.postcode}; revisa fuentes y fecha en la lista.`;}
function exportData(){const text=JSON.stringify(S,null,2);if(native('exportBackup',text))return;const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='MesaChef-copia.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Copia preparada');}
window.importBackup=text=>{try{const candidate=E.validate(JSON.parse(text));for(const id of M.allowedIds())candidate.market.errors[id]='Precio importado: actualiza para consultar la fuente';candidate.market.fetchedAt='';window.pendingImport=candidate;confirmSheet('Restaurar esta copia',`Contiene ${Object.keys(candidate.plan).length} comidas y ${Object.keys(candidate.pantry).length} ingredientes en despensa. Sustituirá los datos actuales de MesaChef.`,'import-confirm','Restaurar');}catch(e){toast('Copia no válida: '+e.message);}};
$('backup-file').addEventListener('change',async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{window.importBackup(await f.text());}catch(e){toast('No se pudo leer esta copia');}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;$('recipe-results').innerHTML=exploreResults();}});
document.addEventListener('keydown',e=>{if(!modal)return;if(e.key==='Escape'){closeSheet();e.preventDefault();}if(e.key==='Tab'){const focus=[...$('sheet').querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(el=>!el.disabled&&!el.hidden&&el.getClientRects().length);const first=focus[0],last=focus.at(-1);if(!first){e.preventDefault();return;}if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('sheet'))){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id,key=b.dataset.key;
 switch(a){
 case 'nav':goto(b.dataset.page);break;
 case 'settings':goto('settings');break;
 case 'close':closeSheet();break;
 case 'generate':generate();break;
 case 'regen':confirmSheet('Otra semana, nuevas ideas','Se conservarán las recetas fijadas. Se reemplazarán las demás y se reiniciarán las marcas de compra y de comidas hechas.','generate','Generar');break;
 case 'recipe':recipeSheet(id,key);break;
 case 'fav':{S.favorites.includes(id)?S.favorites=S.favorites.filter(x=>x!==id):S.favorites.push(id);save();render();if(modal?.type==='recipe')recipeSheet(modal.id,modal.key,true);break;}
 case 'quick':query='';filter='quick';goto('explore');break;
 case 'filter':filter=b.dataset.filter;render();break;
 case 'clear-search':query='';filter='all';render();break;
 case 'pantry-recipes':query='';filter='pantry';goto('explore');break;
 case 'day':selectedDay=Number(b.dataset.day);render();break;
 case 'lock':S.plan[key].locked=!S.plan[key].locked;save();render();break;
 case 'choose':chooseSheet(key);break;
 case 'pick':S.plan[key]={id,servings:S.prefs.people,locked:true};S.cooked=S.cooked.filter(x=>x!==key);S.batchChecks={};S.checks={};save();closeSheet();render();toast('Receta cambiada y fijada');break;
 case 'servings':detailServings=Math.max(1,Math.min(Number.MAX_SAFE_INTEGER,detailServings+Number(b.dataset.delta)));recipeSheet(modal.id,modal.key,true);break;
 case 'schedule':scheduleSheet(id);break;
 case 'remove-meal':confirmSheet('Quitar del menú','Se retirará esta comida y se recalculará la compra.','remove-meal-confirm','Quitar',{key});break;
 case 'remove-meal-confirm':delete S.plan[key];S.cooked=S.cooked.filter(x=>x!==key);S.batchChecks={};S.checks={};save();closeSheet();render();toast('Comida retirada del menú');break;
 case 'check':S.checks[id]=!S.checks[id];save();render();break;
 case 'stock':{const bought=E.shopping(S).filter(x=>S.checks[x.id]&&x.buy!==null);confirmSheet('Guardar la compra',`${bought.length} productos marcados se añadirán a la despensa con la cantidad de los envases comprados. Los productos al peso se añaden manualmente con su cantidad real. Puedes añadir las caducidades después.`,'stock-confirm','Guardar');break;}
 case 'stock-confirm':{const bought=E.shopping(S).filter(x=>S.checks[x.id]&&x.buy!==null);for(const x of bought){S.pantry[x.id]={qty:E.pantryQty(S,x.id)+x.buy,expiry:S.pantry[x.id]?.expiry>=E.localDate()?S.pantry[x.id].expiry:''};delete S.checks[x.id];}save();closeSheet();render();toast('Compra guardada en la despensa');break;}
 case 'pantry-add':pantrySheet();break;
 case 'pantry-edit':pantrySheet(id);break;
 case 'pantry-delete':confirmSheet('Eliminar alimento',`Se eliminará ${esc(I[id].name)} de tu despensa y se recalculará la compra.`,'pantry-delete-confirm','Eliminar',{id});break;
 case 'pantry-delete-confirm':delete S.pantry[id];save();closeSheet();render();toast('Alimento eliminado');break;
 case 'extra':extraSheet();break;
 case 'delete-extra':confirmSheet('Eliminar extra','Este producto se quitará de la lista de compra.','delete-extra-confirm','Eliminar',{id});break;
 case 'delete-extra-confirm':S.extras=S.extras.filter(x=>x.id!==id);delete S.checks[id];save();closeSheet();render();break;
 case 'prices':pricesSheet();break;
 case 'price':priceSheet(id);break;
 case 'price-reset':delete S.receipts[id];S.checks={};save();priceSheet(id);render();toast('Catálogo restaurado');break;
 case 'select-product':S.market.selection[id]=b.dataset.product;delete S.receipts[id];S.checks={};save();priceSheet(id);render();break;
 case 'source':{const p=S.market.products[b.dataset.product];if(p){if(!native('openProduct',p.url))toast('Ficha oficial: '+p.url);}break;}
 case 'refresh-market':refreshMarket(S.market.postcode);break;
 case 'cook':startCook(id,key);break;
 case 'cook-prev':cookStep--;cookSheet(modal.id,modal.key,modal.servings);break;
 case 'cook-next':cookStep++;cookSheet(modal.id,modal.key,modal.servings);break;
 case 'cook-finish':finishCook();break;
 case 'consume':{const slot={id,servings:Number(b.dataset.servings)};let result;if(key){result=E.consume(S,slot,key);}else{const temp={...S,cooked:[]};result=E.consume(temp,slot,'temporary');}save();closeSheet();render();toast(result.error||('Comida terminada'+(result.missing?.length?' · solo se descontó lo disponible':'. Despensa actualizada')));break;}
 case 'timer-start':{const minutes=Number($('timer-minutes').value);if(!Number.isSafeInteger(minutes)||minutes<1||!Number.isFinite(Date.now()+minutes*60000)){toast('Introduce minutos enteros mayores que cero');break;}timerEnd=Date.now()+minutes*60000;timerPaused=0;timerDone=false;updateTimer();break;}
 case 'timer-pause':if(timerPaused){timerEnd=Date.now()+timerPaused;timerPaused=0;}else if(timerEnd>Date.now()){timerPaused=timerEnd-Date.now();timerEnd=0;}updateTimer();break;
 case 'timer-reset':timerEnd=timerPaused=0;timerDone=false;updateTimer();break;
 case 'share-shop':share(shopText());break;
 case 'share-plan':share(planText());break;
 case 'share-recipe':{const r=E.recipe(id);share(`${r.title} · MesaChef\n${detailServings} raciones · ${r.time} min\n\nINGREDIENTES\n`+r.ingredients.map(i=>`${grams(i.g*detailServings)} ${I[i.id].name}`).join('\n')+`\n${r.spices}\n\nPREPARACIÓN\n`+r.steps.map((s,i)=>`${i+1}. ${s}`).join('\n')+(r.note?'\n\n'+r.note:''));break;}
 case 'export':exportData();break;
 case 'import':if(!native('importBackup'))$('backup-file').click();break;
 case 'import-confirm':if(window.pendingImport){cancelMarket();S=window.pendingImport;E.setCustom(S.customRecipes);window.pendingImport=null;save();selectedDay=0;goto('home');toast('Copia restaurada. Consultando los precios de la fuente.');refreshMarket(S.market.postcode);}break;
 case 'reset':confirmSheet('Borrar tus datos','Se eliminarán el menú, la despensa, favoritos, precios editados y preferencias de este dispositivo. Exporta una copia primero si quieres conservarlos.','reset-confirm','Borrar');break;
 case 'reset-confirm':cancelMarket();S=E.defaults();E.setCustom([]);save();goto('home');toast('Datos borrados');break;
 case 'about':showSheet('MesaChef Studio',`<p class="sub">Tu menú y tu compra, con más control.</p><div class="stack"><div class="notice">40 recetas originales · 53 ingredientes · menús con horizonte configurable · raciones ajustables · filtros · favoritos · despensa con fechas · lista por secciones · precios editables · cocina paso a paso · temporizador · copias de seguridad.</div><div class="notice">Carga las últimas fichas publicadas de Mercadona para los códigos postales configurados. GitHub Actions consulta la fuente cada seis horas; puede haber retrasos. «Actualizar» descarga la última consulta publicada, no consulta en directo al supermercado. Las recetas, el menú y la despensa funcionan sin conexión. No compara varias cadenas ni sincroniza dispositivos.</div><div class="notice">Los precios del catálogo incluyen producto, formato, zona y hora de consulta. Sin sustitución por ejemplos. Los productos al peso quedan pendientes de pesar. Las estimaciones nutricionales usan valores genéricos. Los filtros de alergias se basan en ingredientes y no verifican marcas ni trazas.</div><div class="notice">Fotografías de presentación: Unsplash. Son ilustrativas y no representan necesariamente la receta exacta. MesaChef es una app independiente y no está afiliada a CestaChef, Samsung Food ni AnyList.</div></div>`,'about');break;
 }
});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(!f.reportValidity())return;
 switch(f.id){
 case 'settings-form':{const meals=d.getAll('meals');if(!meals.length){toast('Selecciona al menos una comida');return;}const p={name:String(d.get('name')).trim(),people:Number(d.get('people')),budget:Number(d.get('budget')),days:Number(d.get('days')),meals,diet:d.get('diet'),allergens:d.getAll('allergens'),maxTime:Number(d.get('maxTime')),protein:d.has('protein'),start:d.get('start'),theme:d.get('theme')};const candidate=JSON.parse(JSON.stringify(S));let removed=0;const old=candidate.prefs;candidate.prefs=p;for(const [key,slot]of Object.entries(candidate.plan)){const [day,kind]=key.split('-');if(Number(day)>=p.days||!p.meals.includes(kind)||!E.valid(E.recipe(slot.id),p,kind)){delete candidate.plan[key];removed++;}else if(old.people!==p.people)slot.servings=p.people;}candidate.cooked=old.start!==p.start||old.people!==p.people?[]:candidate.cooked.filter(k=>candidate.plan[k]);candidate.checks={};candidate.batchChecks={};try{S=E.validate(candidate);}catch(err){toast('Revisa las preferencias: '+err.message);return;}save();goto('plan');toast(removed?`Preferencias guardadas; ${removed} recetas incompatibles retiradas`:'Preferencias guardadas');break;}
 case 'schedule-form':{const key=d.get('day')+'-'+d.get('kind');S.plan[key]={id:f.dataset.id,servings:detailServings,locked:true};S.cooked=S.cooked.filter(k=>k!==key);S.batchChecks={};S.checks={};save();selectedDay=Number(d.get('day'));goto('plan');toast('Receta añadida y fijada');break;}
 case 'pantry-form':{const id=f.dataset.id||d.get('ingredient');S.pantry[id]={qty:Number(d.get('qty')),expiry:String(d.get('expiry'))};save();closeSheet();render();toast('Despensa actualizada');break;}
 case 'extra-form':if(!String(d.get('name')).trim()){toast('Introduce el nombre del producto');return;}S.extras.push({id:'x'+Date.now(),name:String(d.get('name')).trim(),qty:String(d.get('qty')).trim(),cost:Number(d.get('cost'))});save();closeSheet();render();toast('Producto añadido');break;
 case 'price-form':S.receipts[f.dataset.id]={unitPriceCents:Math.round(Number(d.get('price'))*100),usableG:Number(d.get('pack')),name:I[f.dataset.id].name+' · ticket',fetchedAt:new Date().toISOString()};S.checks={};save();closeSheet();render();toast('Precio del ticket guardado');break;
 case 'market-form':refreshMarket(String(d.get('postcode')));break;
 }
});
function cancelMarket(){marketToken='';marketBusy=false;clearTimeout(marketWatchdog);native('cancelMarket');}
let labTab='rescue',scenario=null,lastUndo=null,draftRows=[],draftValues={};
function rememberUndo(){lastUndo=JSON.parse(JSON.stringify(S));}
function labTabs(){return `<div class="studio-tabs" role="tablist">${[['rescue','leaf','Rescate'],['whatif','spark','¿Y si…?'],['packs','bag','Envases'],['batch','flame','Cocina por lotes']].map(([id,ic,label])=>`<button role="tab" aria-selected="${labTab===id}" data-action="lab-tab" data-tab="${id}" class="${labTab===id?'active':''}">${icon(ic)} ${label}</button>`).join('')}</div>`;}
function labPage(){return `<div class="page-heading"><div><p class="eyebrow">TU ESPACIO PARA DECIDIR MEJOR</p><h1>Bienvenido a <em>Studio.</em></h1><p class="sub">Experimenta con tu cocina. Tú decides qué cambios guardar.</p></div><span class="studio-seal">${icon('spark')} Sin créditos ni cuotas</span></div>${labTabs()}${({rescue:rescueLab,whatif:scenarioLab,packs:packsLab,batch:batchLab}[labTab])()}`;}
function rescueLab(){const list=E.rescue(S),expired=Object.entries(S.pantry).filter(([id,p])=>p.expiry&&p.expiry<E.localDate());return `<div class="intro-card"><div><p class="eyebrow">PRIMERO, LO QUE YA TIENES</p><h2>La despensa marca el camino.</h2><p>Prioriza alimentos con fecha próxima y recetas que requieran menos ingredientes nuevos.</p></div><button class="button secondary" data-action="pantry-add">${icon('plus')} Añadir alimento</button></div>${expired.length?`<p class="notice warn mt">${expired.length} alimentos con fecha vencida quedan fuera de las cantidades disponibles. Revisa su estado en despensa.</p>`:''}${list.length?`<div class="rescue-grid mt">${list.map(x=>`<article class="rescue-item"><button data-action="recipe" data-id="${x.recipe.id}"><img src="./mesachef/images/${x.recipe.image}.jpg" alt="" loading="lazy"><div><p class="eyebrow">${x.urgent.length?'PRIORIDAD POR FECHA':'CON LO QUE TIENES'}</p><h3>${esc(x.recipe.title)}</h3><p>${x.recipe.time} min · ${Math.round(x.coverage*100)} % del peso de ingredientes cubierto</p><div class="coverage-bar"><span style="width:${Math.round(x.coverage*100)}%"></span></div>${x.urgent.length?`<p class="urgent-text">Aprovecha: ${x.urgent.map(id=>esc(I[id].name)).join(', ')}</p>`:''}<p class="small muted">${x.missing.length?`Faltan ${x.missing.length} ingredientes para ${S.prefs.people} raciones.`:'Tienes las cantidades de ingredientes listadas para todas las raciones.'}</p></div></button><button class="text-btn" data-action="rescue-schedule" data-id="${x.recipe.id}">Llevar al menú ${icon('arrow')}</button></article>`).join('')}</div>`:empty('fridge','Una buena cocina empieza en casa','Añade las cantidades de tu despensa para descubrir tus rutas de aprovechamiento.','pantry-add','Añadir lo que tengo')}`;}
function scenarioLab(){const base=E.summary(S);return `<div class="scenario-layout"><form id="scenario-form" class="card"><p class="eyebrow">UN CAMBIO, A MODO DE PRUEBA</p><h2>¿Cómo sería tu menú?</h2><p class="small muted mt">Simula opciones con tus filtros y tu despensa. Las recetas fijadas se conservan cuando son compatibles.</p><div class="field mt"><label for="scenario-diet">Alimentación</label><select id="scenario-diet" name="diet">${[['all','Variada'],['vegetarian','Vegetariana'],['vegan','Vegana']].map(([v,t])=>`<option value="${v}" ${S.prefs.diet===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="scenario-people">Personas</label><input class="input" id="scenario-people" name="people" type="number" min="1" step="1" required value="${S.prefs.people}"></div><div class="field"><label for="scenario-time">Minutos por receta</label><input class="input" id="scenario-time" name="maxTime" type="number" min="1" step="1" required value="${S.prefs.maxTime}"></div></div><div class="field"><label for="scenario-budget">Presupuesto (€)</label><input class="input" id="scenario-budget" name="budget" type="number" min="0" step="0.01" required value="${S.prefs.budget}"></div><button class="button full" type="submit">${icon('spark')} Comparar escenario</button><p class="caption mt">Cálculo local. Puedes volver a simular sin consumir créditos.</p></form><div>${scenario?scenario.error?`<div class="notice warn">${esc(scenario.error)}</div>`:scenarioResult(base):`<div class="scenario-empty"><span>${icon('spark')}</span><h2>Prueba antes de decidir.</h2><p>Verás qué platos cambian, el subtotal de envases con precio y los importes pendientes. Tu menú actual seguirá intacto.</p></div>`}</div></div>`;}
function scenarioResult(base){const next=E.summary(scenario.state),changed=Object.entries(scenario.state.plan).filter(([key,slot])=>S.plan[key]?.id!==slot.id).length;return `<div class="card scenario-result"><p class="eyebrow">TU MENÚ FRENTE A LA PROPUESTA</p><h2>Así cambia la semana.</h2><div class="comparison"><div><span>Actual</span><strong>${euro(base.knownTotal)}</strong><small>${base.complete?'total de productos':'subtotal · total pendiente'}</small></div><div><span>Propuesta</span><strong>${euro(next.knownTotal)}</strong><small>${next.complete?'total de productos':'subtotal · total pendiente'}</small></div></div><div class="scenario-facts"><span><b>${changed}</b> platos diferentes</span><span><b>${next.missing}</b> sin precio vigente</span><span><b>${next.variable}</b> al peso</span></div><p class="notice mt">${base.complete&&next.complete?`Diferencia en envases: ${euro(next.knownTotal-base.knownTotal)}.`:'La diferencia de subtotales no es un ahorro total confirmado: quedan importes pendientes.'} El presupuesto no incluye envío ni básicos no listados.</p><div class="scenario-recipes mt">${Object.values(scenario.state.plan).slice(0,6).map(slot=>`<span>${esc(E.recipe(slot.id).title)}</span>`).join('')}</div><button class="button full mt" data-action="apply-scenario">${icon('check')} Elegir esta propuesta</button></div>`;}
function packsLab(){const rows=E.shopping(S),suggestions=E.packSuggestions(S),fixed=rows.filter(r=>!r.unknown&&!r.variable);return `<div class="intro-card"><div><p class="eyebrow">COMPRA EL FORMATO QUE ENCAJA</p><h2>Piensa en envases, no solo en gramos.</h2><p>Compara alternativas compatibles y mira lo que sobrará después de cocinar tu menú.</p></div><button class="button secondary" data-action="refresh-market">${icon('swap')} Actualizar precios</button></div>${!rows.length?empty('bag','Primero, dale forma a tu menú','La lista pendiente permite comparar cantidades y envases concretos.','generate','Crear mi menú'):''}${suggestions.length?`<div class="section-title"><h2>Alternativas para revisar</h2></div><div class="pack-grid">${suggestions.map(x=>`<article class="card pack-card"><p class="eyebrow">${esc(I[x.ingredient].name)}</p><h3>${esc(x.product.name)}</h3><div class="pack-numbers"><div><b>${euro(x.costCents/100)}</b><span>${x.packs} envase${x.packs===1?'':'s'}</span></div><div><b>${grams(x.remaining)}</b><span>sobrantes calculados</span></div></div><p class="small muted">${productFormat(x.product,x.ingredient)} · ${stamp(x.product.fetchedAt)}</p><p class="notice mt">${x.savingCents>0?`${euro(x.savingCents/100)} menos en estos envases.`:'Mismo importe, menos cantidad sobrante.'} Revisa la etiqueta de esta alternativa.</p><button class="button secondary full mt" data-action="choose-pack" data-id="${x.ingredient}" data-product="${x.product.id}">Elegir este formato</button></article>`).join('')}</div>`:rows.length?'<p class="notice mt">Con los precios vigentes no hay una alternativa que mejore el coste de envases o la cantidad sobrante. Los productos al peso y sin precio quedan fuera de esta comparación.</p>':''}${fixed.length?`<div class="section-title"><h2>Lo que queda para otra receta</h2></div><div class="leftovers">${fixed.map(r=>{const remains=r.buy-r.need;return `<div class="leftover-row"><div><b>${esc(r.name)}</b><span>${r.packs} × ${productFormat(r.product,r.id)}</span></div><div class="leftover-track"><span style="width:${Math.min(100,remains/r.buy*100)}%"></span></div><strong>${grams(remains)}</strong></div>`;}).join('')}</div><p class="caption mt">Son cantidades calculadas antes de comprar; no se incorporan a tu despensa hasta que marques la compra. Líquidos y huevos usan las conversiones declaradas del recetario.</p>`:''}`;}
function batchLab(){const slots=E.batch(S,selectedDay),date=E.dateAt(S.prefs.start,selectedDay),req={};for(const slot of slots)for(const i of slot.recipe.ingredients)req[i.id]=(req[i.id]||0)+i.g*slot.servings;return `<div class="intro-card"><div><p class="eyebrow">PREPARA UNA VEZ, COCINA CON CALMA</p><h2>Tu sesión de cocina.</h2><p>Reúne los ingredientes del día y sigue las recetas sin saltar entre pantallas.</p></div><div class="row"><button class="icon-btn" data-action="batch-day" data-delta="-1" aria-label="Día anterior" ${selectedDay===0?'disabled':''}>${icon('back')}</button><span class="small">${esc(date.toLocaleDateString('es-ES',{day:'numeric',month:'short'}))}</span><button class="icon-btn" data-action="batch-day" data-delta="1" aria-label="Día siguiente" ${selectedDay>=S.prefs.days-1?'disabled':''}>${icon('arrow')}</button></div></div>${slots.length?`<div class="batch-layout mt"><aside class="card batch-ingredients"><p class="eyebrow">TODO A MANO</p><h3>Ingredientes de la sesión</h3>${Object.entries(req).map(([id,g])=>`<div class="ingredient-line"><span>${esc(I[id].name)}</span><b>${grams(g)}</b></div>`).join('')}<p class="caption mt">Pesos totales de las recetas pendientes. No se descuentan de despensa hasta terminar.</p><button class="button full mt" data-action="finish-batch">${icon('check')} Terminar y descontar</button></aside><div class="batch-recipes">${slots.map(slot=>`<article class="card"><p class="eyebrow">${slot.servings} RACIONES · ${slot.recipe.time} MIN ORIENTATIVOS</p><div class="row between"><h2>${esc(slot.recipe.title)}</h2><button class="text-btn" data-action="cook" data-id="${slot.recipe.id}" data-key="${slot.key}">Modo foco ${icon('play')}</button></div><ol class="batch-steps">${slot.steps.map((step,index)=>{const key=slot.key+'-'+index;return `<li class="${S.batchChecks[key]?'done':''}"><button class="check" data-action="batch-check" data-key="${key}" aria-label="Marcar paso ${index+1} de ${esc(slot.recipe.title)}" aria-pressed="${!!S.batchChecks[key]}">${S.batchChecks[key]?icon('check'):index+1}</button><p>${esc(step)}</p></li>`;}).join('')}</ol></article>`).join('')}</div></div>`:empty('calendar','Una sesión todavía por escribir','Añade comidas a este día o elige otro día de tu menú.','generate','Crear mi menú')}`;}
function historyPage(){return `<div class="page-heading"><div><p class="eyebrow">TUS IDEAS, PARA VOLVER A ELLAS</p><h1>Menús que <em>merecen repetirse.</em></h1><p class="sub">Guarda versiones, recupera una semana y sigue construyendo tu recetario.</p></div><button class="button" data-action="save-menu">${icon('plus')} Guardar menú actual</button></div>${S.history.length?`<div class="history-grid">${[...S.history].reverse().map(h=>`<article class="card saved-menu"><span class="history-icon">${icon('calendar')}</span><p class="eyebrow mt">${stamp(h.createdAt)}</p><h2>${esc(h.title)}</h2><p>${h.prefs.days} días · ${h.prefs.people} personas · ${Object.keys(h.plan).length} comidas</p><div class="saved-titles">${Object.values(h.plan).slice(0,3).map(slot=>{const r=h.customRecipes.find(x=>x.id===slot.id)||R.find(x=>x.id===slot.id);return `<span>${esc(r?.title||'Receta guardada')}</span>`;}).join('')}</div><div class="action-pair"><button class="button secondary" data-action="restore-menu" data-id="${h.id}">Usar este menú</button><button class="icon-btn" data-action="delete-menu" data-id="${h.id}" aria-label="Eliminar ${esc(h.title)}">${icon('trash')}</button></div></article>`).join('')}</div>`:empty('calendar','Tu biblioteca empieza contigo','Crea un menú y guarda las semanas que te encajen. Sin un cupo de menús.','generate','Crear mi menú')}`;}
function saveMenuSheet(){if(!Object.keys(S.plan).length){toast('Crea un menú antes de guardarlo');goto('plan');return;}showSheet('Guardar este menú',`<form id="save-menu-form"><div class="field"><label for="menu-title">Nombre para recordarlo</label><input class="input" id="menu-title" name="title" maxlength="200" required value="${esc('Mi menú de '+E.dateAt(S.prefs.start,0).toLocaleDateString('es-ES',{day:'numeric',month:'long'}))}"></div><p class="notice">Guarda recetas, raciones y preferencias. Al recuperarlo se usarán tu despensa y los precios vigentes.</p><button class="button full mt" type="submit">${icon('heart')} Guardar en mis menús</button></form>`,'save-menu');}
function collectDraft(){const f=$('recipe-editor');if(!f)return;const d=new FormData(f);draftValues=Object.fromEntries(d.entries());draftRows=[...f.querySelectorAll('.recipe-draft-row')].map(row=>({id:row.querySelector('select').value,g:row.querySelector('input').value}));}
function recipeEditor(id=null,keep=false){if(!keep){const r=id?E.recipe(id):null;draftRows=r?r.ingredients.map(i=>({...i})): [{id:'arroz',g:''}];draftValues=r?{title:r.title,time:r.time,kind:r.kind,image:r.image,steps:r.steps.join('\n'),spices:r.spices,equipment:r.equipment,note:r.note}:{title:'',time:20,kind:'main',image:'bowl',steps:'',spices:'',equipment:'',note:''};}
 showSheet(id?'Editar mi receta':'Una receta con tu firma',`<form id="recipe-editor" data-id="${id||''}"><div class="field"><label for="custom-title">Nombre del plato</label><input class="input" id="custom-title" name="title" maxlength="200" required value="${esc(draftValues.title)}" placeholder="Tu próxima especialidad"></div><div class="form-grid"><div class="field"><label for="custom-time">Tiempo (minutos)</label><input class="input" id="custom-time" name="time" type="number" min="1" step="1" required value="${draftValues.time}"></div><div class="field"><label for="custom-kind">Tipo de comida</label><select id="custom-kind" name="kind"><option value="main" ${draftValues.kind==='main'?'selected':''}>Plato principal</option><option value="breakfast" ${draftValues.kind==='breakfast'?'selected':''}>Desayuno</option></select></div></div><h3>Ingredientes para una ración</h3><p class="caption mb">Pesos en crudo o escurridos. El catálogo contiene ${Object.keys(I).length} ingredientes; sus productos conservan su fuente y formato.</p>${draftRows.map((i,index)=>`<div class="recipe-draft-row"><label class="sr-only" for="draft-ingredient-${index}">Ingrediente ${index+1}</label><select id="draft-ingredient-${index}">${Object.values(I).sort((a,b)=>a.name.localeCompare(b.name,'es')).map(ingredient=>`<option value="${ingredient.id}" ${i.id===ingredient.id?'selected':''}>${esc(ingredient.name)}</option>`).join('')}</select><label class="sr-only" for="draft-grams-${index}">Gramos por ración</label><input class="input" id="draft-grams-${index}" type="number" min="1" step="1" required value="${i.g}" placeholder="g"><button type="button" class="small-icon" data-action="remove-draft" data-index="${index}" aria-label="Quitar ingrediente" ${draftRows.length===1?'disabled':''}>${icon('trash')}</button></div>`).join('')}<button type="button" class="text-btn" data-action="add-draft">${icon('plus')} Otro ingrediente</button><div class="field mt"><label for="custom-steps">Pasos (uno por línea)</label><textarea class="input" id="custom-steps" name="steps" rows="6" required placeholder="Explica cómo lo preparas…">${esc(draftValues.steps)}</textarea></div><div class="field"><label for="custom-equipment">Equipamiento</label><input class="input" id="custom-equipment" name="equipment" maxlength="500" value="${esc(draftValues.equipment)}" placeholder="Sartén, horno…"></div><div class="field"><label for="custom-spices">Condimentos y básicos</label><input class="input" id="custom-spices" name="spices" maxlength="500" value="${esc(draftValues.spices)}" placeholder="No cuentan en el presupuesto salvo que los añadas como extra"></div><div class="field"><label for="custom-note">Notas</label><textarea class="input" id="custom-note" name="note" maxlength="2000" rows="2">${esc(draftValues.note)}</textarea></div><input type="hidden" name="image" value="${draftValues.image}"><p class="notice">Nutrición y alérgenos se calculan con los ingredientes genéricos; comprueba productos y trazas. La fotografía será ilustrativa.</p><button class="button full mt" type="submit">${icon('check')} Guardar mi receta</button>${id?`<button type="button" class="text-btn full mt" data-action="delete-recipe" data-id="${id}" style="color:var(--danger)">${icon('trash')} Eliminar esta receta</button>`:''}</form>`,'recipe-editor',{id});}
function commandSheet(){showSheet('Encuentra tu próxima idea',`<form id="command-form"><div class="search">${icon('search')}<input class="input" id="command-search" name="query" type="search" placeholder="Plato o ingrediente…" autocomplete="off" aria-label="Buscar recetas"></div></form><div id="command-results">${commandResults('')}</div>`,'command');$('command-search').focus();}
function commandResults(query){const q=normalize(query),list=R.filter(allowed).filter(r=>normalize(r.title+' '+r.ingredients.map(i=>I[i.id].name).join(' ')).includes(q));return list.slice(0,12).map(r=>`<button class="list-choice" data-action="recipe" data-id="${r.id}"><img src="./mesachef/images/${r.image}.jpg" alt=""><div><h3>${esc(r.title)}</h3><p>${r.time} min · ${r.custom?'Tu receta':'Recetario'}</p></div>${icon('arrow')}</button>`).join('')||'<p class="notice mt">No hay coincidencias con tus filtros actuales. Puedes cambiarlos en Preferencias.</p>';}
document.addEventListener('input',event=>{if(event.target.id==='command-search')$('command-results').innerHTML=commandResults(event.target.value);});
document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();commandSheet();}});
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const id=b.dataset.id;switch(b.dataset.action){
 case 'lab-tab':labTab=b.dataset.tab;goto('lab');break;
 case 'command':commandSheet();break;
 case 'new-recipe':recipeEditor();break;
 case 'edit-recipe':recipeEditor(id);break;
 case 'add-draft':{const recipeId=modal?.id;collectDraft();const next=Object.keys(I).find(key=>!draftRows.some(i=>i.id===key));if(!next){toast('Ya están todos los ingredientes del catálogo en esta receta');break;}draftRows.push({id:next,g:''});recipeEditor(recipeId,true);break;}
 case 'remove-draft':{const recipeId=modal?.id;collectDraft();draftRows.splice(Number(b.dataset.index),1);recipeEditor(recipeId,true);break;}
 case 'delete-recipe':confirmSheet('Eliminar mi receta','Se quitará de tu recetario, favoritos y menú actual. Los menús guardados conservan su propia copia.','delete-recipe-confirm','Eliminar',{id});break;
 case 'delete-recipe-confirm':rememberUndo();S.customRecipes=S.customRecipes.filter(r=>r.id!==id);S.favorites=S.favorites.filter(key=>key!==id);for(const [key,slot]of Object.entries(S.plan))if(slot.id===id)delete S.plan[key];S.cooked=S.cooked.filter(key=>S.plan[key]);E.setCustom(S.customRecipes);S.batchChecks={};S.checks={};save();goto('explore');toast('Receta eliminada. Puedes deshacer el cambio.');break;
 case 'rescue-schedule':detailServings=S.prefs.people;scheduleSheet(id);break;
 case 'week-prev':selectedDay=Math.max(0,Math.floor(selectedDay/7)*7-7);render();break;
 case 'week-next':selectedDay=Math.min(S.prefs.days-1,Math.floor(selectedDay/7)*7+7);render();break;
 case 'save-menu':saveMenuSheet();break;
 case 'restore-menu':{const h=S.history.find(h=>h.id===id);if(!h)break;rememberUndo();const historicalIds=new Set(h.customRecipes.map(r=>r.id)),customs=[...S.customRecipes.filter(r=>!historicalIds.has(r.id)),...JSON.parse(JSON.stringify(h.customRecipes))];const candidate={...S,prefs:{...h.prefs,start:E.localDate()},plan:JSON.parse(JSON.stringify(h.plan)),customRecipes:customs,cooked:[],checks:{},batchChecks:{}};try{S=E.validate(candidate);E.setCustom(S.customRecipes);save();selectedDay=0;goto('plan');toast('Menú recuperado desde hoy, con tu despensa y precios actuales');}catch(e){toast(e.message);}break;}
 case 'delete-menu':confirmSheet('Eliminar menú guardado','Se quitará de tu biblioteca. El menú actual seguirá disponible.','delete-menu-confirm','Eliminar',{id});break;
 case 'delete-menu-confirm':rememberUndo();S.history=S.history.filter(h=>h.id!==id);save();goto('history');toast('Menú retirado. Puedes deshacer el cambio.');break;
 case 'apply-scenario':if(scenario&&!scenario.error){rememberUndo();S.prefs=scenario.state.prefs;S.plan=scenario.state.plan;S.cooked=[];S.checks={};S.batchChecks={};S.generation++;save();selectedDay=0;goto('plan');toast('Propuesta elegida. Puedes deshacer el cambio.');}break;
 case 'choose-pack':{const suggestion=E.packSuggestions(S).find(x=>x.ingredient===id&&x.product.id===b.dataset.product);if(!suggestion){toast('La opción cambió. Revisa los precios y cantidades.');render();break;}rememberUndo();S.market.selection[id]=suggestion.product.id;S.checks={};save();render();toast('Formato elegido. Compra recalculada.');break;}
 case 'batch-day':selectedDay=Math.max(0,Math.min(S.prefs.days-1,selectedDay+Number(b.dataset.delta)));render();break;
 case 'batch-check':S.batchChecks[b.dataset.key]=!S.batchChecks[b.dataset.key];save();render();break;
 case 'finish-batch':{const count=E.batch(S,selectedDay).length;confirmSheet('Terminar la sesión',`Se marcarán ${count} comidas como hechas y se descontarán solo las cantidades disponibles.`, 'finish-batch-confirm','Terminar');break;}
 case 'finish-batch-confirm':rememberUndo();for(const slot of E.batch(S,selectedDay))E.consume(S,{id:slot.recipe.id,servings:slot.servings},slot.key);save();closeSheet();render();toast('Sesión terminada. Despensa actualizada.');break;
 case 'undo':if(lastUndo){const previous=lastUndo;lastUndo=null;S=previous;E.setCustom(S.customRecipes);save();closeSheet();render();toast('Último cambio deshecho');}break;
 case 'install':if(window.MesaInstall){window.MesaInstall.prompt();window.MesaInstall=null;}else showSheet('Tu cocina en la pantalla de inicio','<p class="sub">En Chrome para Android, abre el menú ⋮ y elige «Añadir a pantalla de inicio» o «Instalar aplicación». En Safari para iPhone, pulsa Compartir y «Añadir a pantalla de inicio».</p><p class="notice">Abre primero esta web en el navegador completo. El menú y la despensa se guardan en ese navegador.</p>','install');break;
 }});
document.addEventListener('submit',event=>{const f=event.target,d=new FormData(f);if(!f.reportValidity())return;switch(f.id){
 case 'scenario-form':{const candidate=JSON.parse(JSON.stringify(S));candidate.prefs={...S.prefs,diet:d.get('diet'),people:Number(d.get('people')),maxTime:Number(d.get('maxTime')),budget:Number(d.get('budget'))};for(const slot of Object.values(candidate.plan))slot.servings=candidate.prefs.people;candidate.cooked=[];const result=E.generate(candidate);scenario=result.error?{error:result.error}:{state:{...candidate,plan:result.plan}};render();break;}
 case 'save-menu-form':S.history.push({id:'h'+crypto.randomUUID(),title:String(d.get('title')).trim(),createdAt:new Date().toISOString(),prefs:{...S.prefs},plan:JSON.parse(JSON.stringify(S.plan)),customRecipes:JSON.parse(JSON.stringify(S.customRecipes))});save();goto('history');toast('Menú guardado en tu biblioteca');break;
 case 'recipe-editor':{collectDraft();try{const r=E.normalizeRecipe({id:f.dataset.id||'u'+crypto.randomUUID(),...draftValues,time:Number(draftValues.time),ingredients:draftRows.map(i=>({id:i.id,g:Number(i.g)})),steps:String(draftValues.steps).split('\n').map(x=>x.trim()).filter(Boolean)});rememberUndo();const customs=S.customRecipes.filter(x=>x.id!==r.id);customs.push(r);S.customRecipes=customs;E.setCustom(customs);for(const [key,slot]of Object.entries(S.plan))if(slot.id===r.id&&!E.valid(r,S.prefs,key.split('-')[1]))delete S.plan[key];S.cooked=S.cooked.filter(key=>S.plan[key]&&S.plan[key].id!==r.id);S.batchChecks={};S.checks={};save();goto('explore');toast('Tu receta ya forma parte de la cocina');}catch(e){toast(e.message);}break;}
 case 'command-form':query=String(d.get('query'));filter='all';goto('explore');break;
 }});

render();if(storageWarning)setTimeout(()=>toast('No se pudieron recuperar los datos. Puedes restaurar una copia.'),500);
window.MesaApp={getState:()=>S,render,generate,goto,validate:E.validate,refreshMarket,shopText};
if(window.MesaNative?.updatePrices&&(!S.market.fetchedAt||Date.now()-Date.parse(S.market.fetchedAt)>6*3600000))setTimeout(()=>refreshMarket(S.market.postcode),1200);
